effect.shader:
void main(){
vec2 uv = acScreenNorm;
vec2 c = vec2(punchCX * 0.01, punchCY * 0.01);
float p = pow(clamp(punchAmt, 0.0, 1.0), punchCurvePow);
float zoom = 1.0 - p * punchScale * 0.5;
vec2 suv = c + (uv - c) / max(zoom, 0.05);
vec3 col;
if (punchChroma > 0.001 && p > 0.001) {
float ch = punchChroma * p * 0.004;
vec2 dir = (suv - c);
col.r = texture2DCv(inputImg.texture, clamp(suv - dir * ch, 0.0, 1.0)).r;
col.g = texture2DCv(inputImg.texture, clamp(suv, 0.0, 1.0)).g;
col.b = texture2DCv(inputImg.texture, clamp(suv + dir * ch, 0.0, 1.0)).b;
} else {
col = texture2DCv(inputImg.texture, clamp(suv, 0.0, 1.0)).rgb;
}
vec4 outC = texture2DCv(inputImg.texture, clamp(suv, 0.0, 1.0));
gl_FragColor = vec4(col, outC.a);
}
